function subsequencesWithMiddleMode(nums) {
  const n = BigInt(nums.length);
  const pairs = k => k * (k - 1n) / 2n;
  const left = new Map();
  const right = new Map();
  for (const num of nums) right.set(num, (right.get(num) ?? 0n) + 1n);
  // Sums over every value, where l and r are its counts left and right of the middle.
  let leftPairs = 0n; // sum of C(l, 2)
  let rightPairs = 0n; // sum of C(r, 2)
  let cross = 0n; // sum of l * r
  let crossRight = 0n; // sum of l * r * r
  let crossLeft = 0n; // sum of l * l * r
  const shift = (l, r, sign) => {
    leftPairs += sign * pairs(l);
    rightPairs += sign * pairs(r);
    cross += sign * l * r;
    crossRight += sign * l * r * r;
    crossLeft += sign * l * l * r;
  };
  for (const count of right.values()) shift(0n, count, 1n);
  let total = 0n;

  for (let i = 0; i < nums.length; i++) {
    const x = nums[i];
    const sameLeft = left.get(x) ?? 0n;
    const sameRight = right.get(x) - 1n;
    shift(sameLeft, sameRight + 1n, -1n);
    const before = BigInt(i);
    const after = n - 1n - before;
    const otherLeft = before - sameLeft;
    const otherRight = after - sameRight;
    const all = pairs(before) * pairs(after);
    const noCopy = pairs(otherLeft) * pairs(otherRight);
    const clashLeft = sameLeft * (otherLeft * rightPairs + otherRight * cross - crossRight);
    const clashRight = sameRight * (otherRight * leftPairs + otherLeft * cross - crossLeft);
    total += all - noCopy - clashLeft - clashRight;
    left.set(x, sameLeft + 1n);
    right.set(x, sameRight);
    shift(sameLeft + 1n, sameRight, 1n);
  }
  return Number(total % 1000000007n);
}

