function subsequencesWithMiddleMode(nums) {
  const n = nums.length;
  let count = 0;
  for (let a = 0; a < n; a++)
    for (let b = a + 1; b < n; b++)
      for (let c = b + 1; c < n; c++)
        for (let d = c + 1; d < n; d++)
          for (let e = d + 1; e < n; e++) {
            const seq = [nums[a], nums[b], nums[c], nums[d], nums[e]];
            const times = v => seq.filter(w => w === v).length;
            if (seq.every(v => v === seq[2] || times(v) < times(seq[2]))) count++;
          }
  return count % 1000000007;
}

