function generate(rand, size) {
  const n = size === 'large' ? 2000 : 5 + Math.floor(rand() * 8);
  const kinds = size === 'large' ? [2, 6, 40, 2000] : [1, 2, 3, 4, 6, 12];
  const kind = kinds[Math.floor(rand() * kinds.length)];
  const pool = Array.from({ length: kind }, () => Math.floor(rand() * 2000000001) - 1000000000);
  if (rand() < 0.3) pool[0] = rand() < 0.5 ? -1000000000 : 1000000000;
  return [Array.from({ length: n }, () => pool[Math.floor(rand() * kind)])];
}
